import * as rt from '@midnight-ntwrk/compact-runtime';
import { Contract, ledger } from './c/index.js';
const sk = (n)=>new Uint8Array(32).fill(n);
const mk = (n)=>new Contract({ secretKey: ({privateState})=>[privateState, sk(n)] });
const admin = mk(1), alice = mk(2);
const pk = (n)=>admin.circuits.publicKey? null:null;
const { pureCircuits } = await import('./c/index.js');
const A = pureCircuits.publicKey(sk(1)), B = pureCircuits.publicKey(sk(2));
const coinPk = '0'.repeat(64);
let ctx = rt.constructorContext({}, coinPk);
const init = admin.initialState(ctx);
let cc = rt.createCircuitContext(rt.dummyContractAddress(), init.currentZswapLocalState.coinPublicKey, init.currentContractState.data, {});
const show=(l)=>{const s=ledger(cc.currentQueryContext.state);console.log(l,'supply',s.totalSupply,'A',s.balances.member(A)?s.balances.lookup(A):0n,'B',s.balances.member(B)?s.balances.lookup(B):0n);};
const call=(c,name,...a)=>{try{const r=c.impureCircuits[name](cc,...a);cc=r.context;return 'ok'}catch(e){return 'FAIL: '+e.message}};
console.log(call(admin,'mint',B,100n)); show('mint');
console.log('nonadmin mint', call(alice,'mint',B,5n));
console.log(call(alice,'transfer',A,30n)); show('transfer');
console.log('overdraw', call(alice,'transfer',A,999n));
console.log(call(alice,'burn',20n)); show('burn');
console.log('overburn', call(alice,'burn',999n));
EOF
node run.mjs 2>&1 | head -30

